insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('SE', 'default', 'Referenskontoplan för Sverige', '{}'::jsonb, true, 'companies', array['SE-ARL-BIL1-BS', 'SE-ARL-BIL2-IS']::text[], null, 'Bokföringslagen ställer inte upp någon lagstadgad kontoplan; kraven är att bokföringen är systematisk och kan presenteras i en systematisk ordning (5 kap. 1 §). Den vidast spridda referensen i svensk praxis är den kontoklassindelning som BAS-kontoplanen bygger på (klass 1 tillgångar, klass 2 eget kapital och skulder, klass 3 rörelsens intäkter, klass 4 material och varor, klass 5–6 övriga externa kostnader, klass 7 personalkostnader och avskrivningar, klass 8 finansiella poster och skatt). Denna plan följer den indelningen som referens men är Ekwos egen sammanställning: den återger varken BAS-kontoplanens fullständiga kontolista, dess kontonummer eller dess benämningar, som är Bas-intressenternas Förenings verk och inte publiceras under en öppen licens.', 'bokforingslagen')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

