insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('SE-ARL-BIL1-BS', 'SE', 'default', 'Balansräkning enligt bilaga 1 (kontoform)', 'balance_sheet', 'SE-ARL', date '2016-01-01', null, 'Årsredovisningslag (1995:1554) 3 kap. 3 § första stycket — balansräkningen ska upprättas enligt den uppställningsform som anges i bilaga 1 till denna lag; bilaga 1, Uppställningsform för balansräkningen (kontoform), i den lydelse bilagan fick genom lag (2015:813), som förde in Europaparlamentets och rådets direktiv 2013/34/EU och som tillämpas första gången för det räkenskapsår som inleds närmast efter den 31 december 2015. Uppställningen följer aktiebolagens rad under rubriken A. Eget kapital, eftersom kontoplanen kontot 2010 Aktiekapital bär; posterna för ekonomiska föreningar, handelsbolag och övriga företagsformer, som bilagan ger som alternativ under samma rubrik, används inte av denna plan. Denna lag ställer inte upp någon kontoplan — se legal_reference på chart ''default'' i pack.json — så varje rad nedan är en av Ekwos egna kontointervall i det plan denna pack bär, inte ett återgivande av BAS-kontoplanens numrering. En post i bilagan som ingen av kontona i denna pack svarar mot skrivs ut utan regel och läses noll; README räknar upp dem.', 'arsredovisningslagen'),
  ('SE-ARL-BIL2-IS', 'SE', 'default', 'Resultaträkning enligt bilaga 2 (kostnadsslagsindelad)', 'income_statement', 'SE-ARL', date '2016-01-01', null, 'Årsredovisningslag (1995:1554) 3 kap. 3 § andra stycket — resultaträkningen ska upprättas enligt någon av de uppställningsformer som anges i bilagorna 2 och 3; denna pack använder bilaga 2, Uppställningsform I för resultaträkning (rapportform med kostnadsslagsindelning), i den lydelse bilagan fick genom lag (2015:813). Bilaga 3 (funktionsindelning, efter kostnad för sålda varor) bärs inte av denna pack. 2 kap. 2 § tillåter mindre företag att slå samman posterna 1–6 till en post benämnd bruttovinst eller bruttoförlust; den sammanslagningen görs inte här, så varje post i bilagan är en egen rad. En post i bilagan som ingen av kontona i denna pack svarar mot skrivs ut utan regel och läses noll; README räknar upp dem.', 'arsredovisningslagen')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

insert into statement_line_templates
  (statement_code, code, parent_code, name, name_i18n, sequence, sign, is_total,
   plus_lines, minus_lines, xbrl_element, legal_reference, source_key)
